# -*- coding: utf-8 -*-
"""MANAPRINT — VAI · 7 boules · maquette Canva de Maeva (27/11/2026, « vai_canva_16_A4_v4 »).
Reprise TELLE QUELLE : 16 cartes / feuille A4 PAYSAGE (4 x 4), traits de coupe en pointillés.
Chaque carte : VAI, la goutte d'eau et ses ronds, les deux vagues Canva (posées en pochoir : en
couleur, MANAPRINT les repeint, les chiffres restent noirs), 3 bulles à gauche, 3 à droite, N° CARTE.
RÈGLE (celle de VAI, inchangée) : gauche 3 numéros 61-70 · droite 3 numéros 81-90 (dans l'ordre)
   · dans la goutte 1 numéro 71-80.   Crieur : 61 à 90.
Chiffres Times gras noirs 30 pt (bulles agrandies), comme sur la maquette.
Le tout est réduit pour garder 6 mm de marge d'impression (Konica / Sharp)."""

import io, random
from reportlab.pdfgen import canvas
from reportlab.lib.pagesizes import A4, landscape
from reportlab.lib import colors

try:
    from generators import canva_masque as _masque
except Exception:
    import canva_masque as _masque

PAGE_W, PAGE_H = landscape(A4)
COLS, RANGS = 4, 4
CARTES_PAGE = COLS * RANGS                # 16
CELL_W, CELL_H = 210.4724, 148.8189
NOIR = colors.black
POLICE_NUM = "Times-Bold"
# (centre x, ligne de base, taille) : gauche 61-70 ×3, droite 81-90 ×3, goutte 71-80
CASES = [(28.913, 109.134, 30), (28.913, 63.496, 30), (28.913, 17.858, 30),
         (181.559, 109.134, 30), (181.559, 63.496, 30), (181.559, 17.858, 30),
         (105.236, 45.851, 30)]
_IMGS = [(56.12598, 76.53543, 25.51181, 24.37795), (128.8346, 76.53543, 25.51181, 24.37795),
         (61.29921, 24.37795, 87.87402, 21.87659), (85.15568, 30.61417, 40.16109, 90.70866)]

MARGE_SURE = 6 * 72 / 25.4
ECHELLE = min((PAGE_W - 2 * MARGE_SURE) / PAGE_W, (PAGE_H - 2 * MARGE_SURE) / PAGE_H)
DECAL_X = (PAGE_W - PAGE_W * ECHELLE) / 2.0
DECAL_Y = (PAGE_H - PAGE_H * ECHELLE) / 2.0
_DEJA = set()


def _numeros(rng):
    t = None
    for _ in range(500):
        t = tuple(sorted(rng.sample(range(61, 71), 3)) + sorted(rng.sample(range(81, 91), 3))
                  + [rng.randint(71, 80)])
        if t not in _DEJA:
            break
    _DEJA.add(t)
    return t


def _txt(c, s, x, y, police, taille, col, centre=False):
    w = c.stringWidth(s, police, taille)
    t = c.beginText(x - w / 2.0 if centre else x, y); t.setFont(police, taille)
    t.setFillColor(col); t.textOut(s)
    c.drawText(t)


def _en_teinte():
    import sys
    for nom in ("app", "__main__"):
        m = sys.modules.get(nom)
        e = getattr(m, "_TEINTE_ETAT", None) if m else None
        if e is not None and getattr(e, "canva", False):
            return True
    return False


def _modele(c):
    if getattr(c, "_vai_modele", False):
        return
    import base64
    d = _DESSIN
    if _en_teinte():          # version couleur : les bulles grises prennent aussi la couleur du billet
        d = d.replace(".45 .45 .45 RG", "0 0 0 RG").replace(".2 .2 .2 RG", "0 0 0 RG")
    for k, v in (("{HB}", "Helvetica-Bold"), ("{H}", "Helvetica")):
        d = d.replace(k, c._doc.getInternalFontName(v))
    c.beginForm("VAI_CANVA", 0, 0, CELL_W, CELL_H)
    c._code.append("q\n0 g\n0 G")
    morceaux = d
    for i in range(len(_IMGS)):
        morceaux = morceaux.replace("@IMG%d@" % i, "\x00%d\x00" % i)
    for j, part in enumerate(morceaux.split("\x00")):
        if j % 2 == 1:
            i = int(part); x, y, w, h = _IMGS[i]
            _masque.poser(c, "VAI_IMG_%d" % i, base64.b64decode(_PNG[i]), x, y, w, h)
        elif part:
            c._code.append(part)
    c._code.append("Q")
    c.endForm()
    c._vai_modele = True


def _billet(c, ox, oy, serie, nums, col):
    _modele(c)
    c.saveState()
    c.translate(ox, oy)
    c.doForm("VAI_CANVA")
    _txt(c, "%06d" % serie, 116.5788, 12.18898, "Helvetica", 6.2, colors.Color(.15, .15, .15))
    for (x, y, t), n in zip(CASES, nums):
        _txt(c, str(n), x, y, POLICE_NUM, t, col, centre=True)
    c.restoreState()


def generer_pdf(nb_cartes=None, nb_tickets=None, serie_start=1, theme="", couleur=True,
                nom_evenement="", titre_jeu="", couleur_perso="", date_lieu="",
                telephone="", page_start=1, evenement_id="", style="", motif="", **_ig):
    n_ = nb_cartes if nb_cartes is not None else nb_tickets
    n_ = max(1, int(n_ if n_ else CARTES_PAGE))
    buf = io.BytesIO()
    c = canvas.Canvas(buf, pagesize=(PAGE_W, PAGE_H), pageCompression=1)
    c.setTitle("VAI · 7 boules")
    rng = random.Random(int(serie_start) * 100003 + 2713)
    _DEJA.clear()
    serie = int(serie_start)
    faits = 0
    try:
        no_page = max(1, int(page_start))
    except Exception:
        no_page = 1
    while faits < n_:
        c.setFillColor(colors.Color(0.5, 0.5, 0.5)); c.setFont("Helvetica", 7)
        c.drawRightString(PAGE_W - DECAL_X, PAGE_H - DECAL_Y / 2.0 - 2.5, "page %d" % no_page)
        entete = "  ·  ".join(t for t in ((nom_evenement or "").strip(), (date_lieu or "").strip()) if t)
        if entete:
            c.setFillColor(NOIR); c.setFont("Helvetica-Bold", 7)
            c.drawCentredString(PAGE_W / 2.0, PAGE_H - DECAL_Y / 2.0 - 2.5, entete)
        c.saveState()
        c.translate(DECAL_X, DECAL_Y); c.scale(ECHELLE, ECHELLE)
        for idx in range(CARTES_PAGE):
            if faits >= n_:
                break
            ox = (idx % COLS) * CELL_W
            oy = (RANGS - 1 - idx // COLS) * CELL_H
            _billet(c, ox, oy, serie, _numeros(rng), NOIR)
            serie += 1
            faits += 1
        c.setStrokeColor(colors.Color(0.5, 0.5, 0.5)); c.setLineWidth(0.3); c.setDash(2, 2)
        for i in range(1, COLS):
            c.line(i * CELL_W, 0, i * CELL_W, RANGS * CELL_H)
        for j in range(1, RANGS):
            c.line(0, j * CELL_H, COLS * CELL_W, j * CELL_H)
        c.restoreState()
        c.showPage()
        no_page += 1
    c.save()
    buf.seek(0)
    return buf


